mapper.update:
UPDATE purchase_order
supplier_id = #{supplierId}, warehouse_id = #{warehouseId}, total_amount = #{totalAmount}, status = #{status}, order_date = #{orderDate}, remark = #{remark}, company_id = #{companyId}, delivery_method = #{deliveryMethod}, is_tax_included = #{isTaxIncluded}, tax_rate = #{taxRate}, tax_amount = #{taxAmount}, untaxed_amount = #{untaxedAmount}, invoice_done = #{invoiceDone}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.select:
SELECT po.order_no, s.supplier_name, p.sku_code, p.product_name, p.spec, poi.quantity, poi.price, poi.amount, po.order_date, u.real_name as purchaser_name, CASE po.status WHEN 0 THEN '草稿' WHEN 1 THEN '已入库' WHEN 2 THEN '已取消' END as status_desc FROM purchase_order po LEFT JOIN supplier s ON po.supplier_id = s.id LEFT JOIN purchase_order_item poi ON po.id = poi.order_id LEFT JOIN product p ON poi.product_id = p.id LEFT JOIN sys_user u ON po.purchaser_id = u.id WHERE po.status = 1
AND po.order_date >= #{startDate}
AND po.order_date <= #{endDate}
AND po.supplier_id = #{supplierId}
AND po.warehouse_id = #{warehouseId}
ORDER BY po.order_date DESC, po.order_no DESC

SELECT po.id, po.order_no, po.supplier_id, s.supplier_name, po.warehouse_id, po.total_amount, po.status, po.purchaser_id, po.order_date, po.remark, po.created_at, po.company_id, po.delivery_method, po.is_tax_included, po.tax_rate, po.tax_amount, po.untaxed_amount, po.invoice_done FROM purchase_order po LEFT JOIN supplier s ON po.supplier_id = s.id WHERE 1=1
AND po.company_id = #{companyId}
AND po.order_no LIKE CONCAT('%', #{orderNo}, '%')
ORDER BY po.created_at DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM purchase_order po WHERE 1=1
AND po.company_id = #{companyId}
AND po.order_no LIKE CONCAT('%', #{orderNo}, '%')
